import test from "node:test";
import assert from "node:assert/strict";
import { splitEvenly } from "../../src/pricing.mjs";

test("splitEvenly hands the remainder to the earliest shares first", () => {
  assert.deepEqual(splitEvenly(10, 3), [4, 3, 3]);
});

test("splitEvenly adds nothing extra when the total divides evenly", () => {
  assert.deepEqual(splitEvenly(9, 3), [3, 3, 3]);
});

test("splitEvenly's parts always sum back to the total", () => {
  const parts = splitEvenly(10, 3);
  assert.equal(parts.reduce((a, b) => a + b, 0), 10);
});

test("splitEvenly rejects a non-positive share count", () => {
  assert.throws(() => splitEvenly(10, 0), RangeError);
});

