import test from "node:test";
import assert from "node:assert/strict";
import { isFreeShipping } from "../../src/pricing.mjs";

test("membership alone qualifies for free shipping even with a 0 total", () => {
  assert.equal(isFreeShipping(0, true), true);
});

test("a large-enough basket alone qualifies for free shipping for a non-member", () => {
  assert.equal(isFreeShipping(5000, false), true);
});

test("neither membership nor a qualifying basket means shipping is not free", () => {
  assert.equal(isFreeShipping(0, false), false);
});

test("a member with a qualifying basket is still free (the OR is inclusive)", () => {
  assert.equal(isFreeShipping(5000, true), true);
});

test("a basket just under the threshold is not free for a non-member", () => {
  assert.equal(isFreeShipping(4999, false), false);
});

