import test from "node:test";
import assert from "node:assert/strict";
import { applyDiscount } from "../../src/pricing.mjs";

test("the discount rounds down so the customer is never charged a fraction of a cent", () => {
  assert.equal(applyDiscount(1, 10), 10);
});

test("a quantity below the lowest band gets no discount at all", () => {
  assert.equal(applyDiscount(100, 5), 500);
});

test("the result is always a whole number of cents", () => {
  assert.equal(Number.isInteger(applyDiscount(1, 10)), true);
});

test("a zero price stays zero regardless of any discount band", () => {
  assert.equal(applyDiscount(0, 10), 0);
});

