import test from "node:test";
import assert from "node:assert/strict";
import { discountPercentFor } from "../../src/pricing.mjs";

test("below the lowest band gets no discount", () => {
  assert.equal(discountPercentFor(9), 0);
});

test("the 10-quantity band edge gets a 5% discount", () => {
  assert.equal(discountPercentFor(10), 5);
});

test("just under the 25 edge is still the 5% band", () => {
  assert.equal(discountPercentFor(24), 5);
});

test("the 25-quantity band edge gets 10% (inclusive at its lower edge)", () => {
  assert.equal(discountPercentFor(25), 10);
});

test("just under the 100 edge is still the 10% band", () => {
  assert.equal(discountPercentFor(99), 10);
});

test("the 100-quantity band edge gets 20%", () => {
  assert.equal(discountPercentFor(100), 20);
});

